function RotaryTableRewardCell:FreshBaseUI(data)
    print("rewardData====>>"..table.dump(data))
    local isBig = data.rewardType == 1
    local isGet = data.num == data.stock    
    KTool.SetActive(self.ImgBigRewardBg, isBig)
    KTool.SetActive(self.ImgBigRewardTips, isBig)
    KTool.SetActive(self.GetNode, isGet)
    local goodNodeEnv = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    goodNodeEnv:Reload(
            {
                goodsId = data.reward,
                text = string.format('x%d', data.rewardNum),
                isShowNo = true,
            }
    )
    CfUtils.SetUISwitchImage(self.NumberNode, isBig and 2 or 1)
    local number
    if data.stock == -1 then
        number = "∞"
    else
        number = data.stock - data.num
    end
    CfUtils.FillText(self.TxtNumber, number)
end

